using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class PersonnelTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Personnel: "+name);}}
 static void Call(object o,string method,params object[] args){o.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic,null,Array.ConvertAll(args,a=>a.GetType()),null).Invoke(o,args);}
 static Simulation Dress(Franchise f){Simulation s=new Simulation(312);f.Apply(s,(f.UserTeam+1)%12);s.NewGame();return s;}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-personnel-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{Franchise f=Franchise.Create(new Profile(),new Roster());ClubPlayer starter=f.Starter(f.UserTeam,1),backup=f.Players.Find(p=>p.Team==f.UserTeam&&p.Role=="RB"&&p.Slot<0);int starterNumber=starter.Number,backupNumber=backup.Number;starter.InjuryWeeks=4;Simulation s=Dress(f);Check(s.Players[1].ClubId==backup.Id&&s.Players[1].Number==backupNumber&&s.Players[1].Number!=starterNumber,"injured back replaced by actual reserve with own jersey");Check(s.Players[1].Name==backup.Name&&s.PersonnelNotice.Contains("#"+backupNumber),"reserve name and substitution notice identify real player");backup.InjuryWeeks=2;s=Dress(f);Check(!s.Players[1].Active&&s.Players[1].ClubId<0&&s.OnFieldCount(0)==10,"no healthy RB means empty spot and ten players");s.RunPlay=true;s.Playbook=6;s.Snap();for(int i=0;i<30;i++)s.Update(.02f,0,0);Check(s.Controlled.Role=="QB"&&s.Controlled.HasBall&&!s.HandoffPending,"missing RB cannot receive automatic phantom handoff");s.BeginPass(3);Check(!s.Charging,"empty receiver slot cannot be targeted");
  foreach(ClubPlayer p in f.Squad(f.UserTeam))if(p.Role=="QB")p.InjuryWeeks=3;s=Dress(f);HashSet<int> ids=new HashSet<int>();bool distinct=true;foreach(Player p in s.Players)if(p.Team==0&&p.Active)distinct&=p.ClubId>0&&ids.Add(p.ClubId);Check(s.Wildcat&&s.Controlled.Active&&s.Controlled.ClubId>0&&distinct&&s.OnFieldCount(0)==9,"QB shortage uses one existing player at wildcat without cloning roster");
  ClubPlayer a=f.Squad(f.UserTeam)[4],b=f.Squad(f.UserTeam)[5];b.Number=a.Number;f.EnsureJerseyNumbers();HashSet<int> jerseys=new HashSet<int>();bool unique=true;foreach(ClubPlayer p in f.Squad(f.UserTeam))unique&=jerseys.Add(p.Number);Check(unique,"legacy duplicate jersey numbers become unique within club");f.Save();Franchise loaded=Franchise.Load(new Profile(),new Roster());Check(loaded.Players.Find(p=>p.Id==backup.Id).Number==backupNumber,"reserve jersey identity persists in save");
  int connected=0;for(int seed=0;seed<20;seed++){s=new Simulation(seed+120);s.Practice=true;s.NewGame();s.RunPlay=true;s.Playbook=6;s.Snap();for(int i=0;i<24;i++)s.Update(.02f,0,0);if(seed==0)Check(s.HandoffOccurred&&s.Controlled.Role=="RB","real handoff gives RB possession behind line");if(!s.Lateral())continue;for(int i=0;i<100&&s.State==Phase.Flight;i++)s.Update(.02f,0,0);if(s.State==Phase.Live&&s.Controlled.Role=="QB"){connected++;if(seed==0)Check(s.CanThrow&&!s.BallCrossedScrimmage&&!s.RunPlay,"returned pitch unlocks QB forward pass and receiver routes");s.BeginPass(0);s.Charge=.35f;s.ReleasePass();if(seed==0)Check(s.State==Phase.Flight&&s.Attempts==1,"flea flicker produces real forward pass after backward pitch");}}
  Console.WriteLine("Flea-flicker return pitches: "+connected+" / 20");Check(connected>=12,"backward RB pitch can reliably reach actual QB");s=new Simulation(5);s.Snap();s.Controlled.Z=s.Spot+1;s.Update(.01f,0,0);s.Controlled.Z=s.Spot-2;Check(s.BallCrossedScrimmage&&!s.CanThrow,"crossing line then retreating cannot restore forward pass");s.Next();s.NewGame();s.Snap();s.BeginPass(0);s.ReleasePass();Call(s,"ReturnedPitch",s.Players[0]);Check(!s.CanThrow,"previous forward pass cannot be reset by flea flicker");
  Console.WriteLine("Personnel: "+checks+" checks, "+failures+" failures");return failures;
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
}
